<?php
/** Proof — requesters (spec "Proof", 5): a known address → 422 with the link; a member's name is the mirror's; addresses; merge moves tickets, emails and ratings; a member into an external → refused. */
require __DIR__ . '/lib.php';
$marco = as_member(27); $lena = as_member(28);
$general = general_queue();

echo "1. Add an external by hand\n";
$org = (int) one("INSERT INTO organizations (name) VALUES ('SMOKE Initech') RETURNING id");
q("INSERT INTO organization_domains (domain, organization_id) VALUES ('initech.invalid', :o)", ['o' => $org]);
$since = last_activity_id();
[$c, $b] = act($marco, '/requesters/save.php', ['display_name' => 'SMOKE Bob', 'email' => 'Bob@Initech.invalid', 'phone' => '+1 555 0101', 'locale' => 'en', 'timezone' => 'America/Chicago', 'notes' => 'SMOKE bob note']);
$bob = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $bob > 0 && ($b['location'] ?? '') === '/requesters/' . $bob . '?notice=saved', "requester_create: 200, record_id $bob");
$row = q('SELECT kind, display_name, primary_email::text AS email, organization_id, timezone FROM requesters WHERE id = :r', ['r' => $bob])[0];
ok($row['kind'] === 'external' && $row['email'] === 'bob@initech.invalid' && (int) $row['organization_id'] === $org && $row['timezone'] === 'America/Chicago', 'an external, lower-cased address, claimed by Initech\'s domain, the fields set');
ok(count(activity('requester.create', $since)) === 1 && !str_contains((string) activity('requester.create', $since)[0]['after'], 'bob note'), 'requester.create logged without the notes\' text');
[$c, $b] = act($marco, '/requesters/save.php', ['display_name' => 'SMOKE Bob again', 'email' => 'bob@initech.invalid']);
ok($c === 422 && msg($b) === 'That address belongs to SMOKE Bob — open them instead.' && ($b['error']['record_id'] ?? ($b['record_id'] ?? 0)) == $bob || ($c === 422 && str_contains(msg($b), 'belongs to SMOKE Bob')), 'a known address: 422 "That address belongs to SMOKE Bob — open them instead."');
[$c, $b] = act($marco, '/requesters/save.php', ['display_name' => 'SMOKE Marco twin', 'email' => 'marco@example.invalid']);
ok($c === 422 && str_contains(msg($b), 'belongs to SMOKE Marco'), 'a member\'s address: 422 naming the member');
[$c, $b] = act($marco, '/requesters/save.php', ['display_name' => 'SMOKE No mail']);
ok($c === 422 && isset(fields($b)['email']), 'no email on a create: 422 (field email)');
[$c, $b] = act($marco, '/requesters/save.php', ['display_name' => 'SMOKE Zone', 'email' => 'zone@initech.invalid', 'timezone' => 'Mars/Olympus']);
ok($c === 422 && isset(fields($b)['timezone']), 'a bad time zone: 422');

echo "2. A member's row is the mirror's\n";
$mreq = requester_of_member(27);
[$c, $b] = act($lena, '/requesters/save.php', ['requester' => $mreq, 'display_name' => 'SMOKE Renamed', 'notes' => 'SMOKE lead note', 'organization' => $org]);
ok($c === 200 && (string) one('SELECT display_name FROM requesters WHERE id = :r', ['r' => $mreq]) === 'SMOKE Marco' && (int) one('SELECT organization_id FROM requesters WHERE id = :r', ['r' => $mreq]) === $org, 'a forced name change on a member is ignored; organization and notes saved');
$body = page($lena, '/requesters/' . $mreq)['body'];
ok(str_contains($body, 'Managed by the OS') && str_contains($body, 'id="requester-view-notes"') && !str_contains($body, 'id="requester-email-form"'), 'the page says "Managed by the OS" and offers no address form');
ok(str_contains(page($lena, '/requesters/' . $mreq . '/edit')['body'], 'id="requester-form-name-ro"'), 'the form shows the name read-only');
[$c, $b] = act($marco, '/requesters/email.php', ['requester' => $mreq, 'email' => 'other@example.invalid']);
ok($c === 422, 'adding an address to a member: 422');

echo "3. Addresses\n";
[$c, $b] = act($marco, '/requesters/email.php', ['requester' => $bob, 'email' => 'Robert@initech.invalid']);
ok($c === 200 && (int) one('SELECT count(*) FROM requester_emails WHERE requester_id = :r', ['r' => $bob]) === 2, 'requester_email_add: a second address');
[$c, $b] = act($marco, '/requesters/email.php', ['requester' => $bob, 'email' => 'marco@example.invalid']);
ok($c === 422 && str_contains(msg($b), 'belongs to SMOKE Marco'), 'an address that is someone else\'s: 422 naming them');
[$c, $b] = act($marco, '/requesters/email.php', ['requester' => $bob, 'email' => 'robert@initech.invalid']);
ok($c === 422 && msg($b) === 'They already have that address.', 'the same address again: 422');
[$c, $b] = act($marco, '/requesters/email-remove.php', ['requester' => $bob, 'email' => 'bob@initech.invalid']);
ok($c === 200 && (string) one('SELECT primary_email FROM requesters WHERE id = :r', ['r' => $bob]) === 'robert@initech.invalid', 'removing the primary makes the other one primary');
[$c, $b] = act($marco, '/requesters/email-remove.php', ['requester' => $bob, 'email' => 'robert@initech.invalid']);
ok($c === 422 && msg($b) === 'A requester keeps at least one address.', 'never the last: 422');
[$c, $b] = act($marco, '/requesters/email-remove.php', ['requester' => $bob, 'email' => 'nobody@initech.invalid']);
ok($c === 404, 'an address they do not have: 404');
[$c, $d] = screen($marco, '/requesters/?q=robert');
ok(count($d['requesters']) === 1 && $d['requesters'][0]['requester_id'] === $bob, 'search finds a requester by any address');
[$c, $d] = screen($marco, '/requesters/?kind=agent');
ok(count(array_filter($d['requesters'], fn ($r) => $r['kind'] !== 'agent')) === 0, 'the kind filter holds');

echo "4. Merge\n";
$dup = external('bobby@elsewhere.invalid', 'SMOKE Bobby');
$t1 = mkticket($dup, $general, 'SMOKE Bobby one'); $t2 = mkticket($dup, $general, 'SMOKE Bobby two', 'solved');
q("INSERT INTO satisfaction_ratings (ticket_id, requester_id, score, token_hash, expires_at) VALUES (:t, :r, 5, :h, now() + interval '30 days')", ['t' => $t2, 'r' => $dup, 'h' => hash('sha256', 'SMOKE ' . $t2)]);
q("INSERT INTO ticket_followers (ticket_id, kind, requester_id) VALUES (:t, 'cc', :r)", ['t' => $t1, 'r' => $dup]);
$body = page($lena, '/requesters/merge.php?requester=' . $dup . '&q=bob')['body'];
ok(str_contains($body, 'id="requester-merge-candidate-' . $bob . '"') && !str_contains($body, 'id="requester-merge-candidate-' . $dup . '"'), 'the merge page searches and lists Bob, never the row itself');
$body = page($lena, '/requesters/merge.php?requester=' . $dup . '&into=' . $bob)['body'];
ok(str_contains($body, "SMOKE Bobby</strong>'s 2 tickets and 1 address move to <strong>SMOKE Bob"), 'the confirm page says what moves');
[$c, $b] = act($lena, '/requesters/merge.php', ['requester' => $dup, 'into' => $dup]);
ok($c === 422 && msg($b) === 'Choose two different requesters.', 'a row into itself: 422');
[$c, $b] = act($lena, '/requesters/merge.php', ['requester' => $mreq, 'into' => $bob]);
ok($c === 422 && msg($b) === 'Merge the external into the member, not the other way.', 'a member into an external: refused');
$since = last_activity_id();
[$c, $b] = act($lena, '/requesters/merge.php', ['requester' => $dup, 'into' => $bob]);
ok($c === 200 && ($b['tickets'] ?? 0) === 2 && ($b['emails'] ?? 0) === 1 && ($b['location'] ?? '') === '/requesters/' . $bob . '?notice=merged', 'requester_merge: 2 tickets and 1 address moved; lands on Bob');
ok((int) one('SELECT requester_id FROM tickets WHERE id = :t', ['t' => $t1]) === $bob && (int) one('SELECT requester_id FROM satisfaction_ratings WHERE ticket_id = :t', ['t' => $t2]) === $bob && (int) one('SELECT requester_id FROM ticket_followers WHERE ticket_id = :t', ['t' => $t1]) === $bob, 'tickets, the rating and the cc point at Bob');
ok((int) one('SELECT merged_into_id FROM requesters WHERE id = :r', ['r' => $dup]) === $bob && (int) one('SELECT count(*) FROM requester_emails WHERE requester_id = :r', ['r' => $bob]) === 2, 'merged_into_id set; Bob now has two addresses');
$log = activity('requester.merge', $since);
ok(count($log) === 1 && str_contains((string) $log[0]['after'], '"into_requester_id": ' . $bob) && str_contains((string) $log[0]['after'], '"tickets": 2'), 'requester.merge logged with into_requester_id and the counts');
ok((int) one("SELECT hd_requester_for_email('bobby@elsewhere.invalid')") === $bob, 'hd_requester_for_email() for the old address now answers Bob');
[$c, $d] = screen($marco, '/requesters/');
ok(count(array_filter($d['requesters'], fn ($r) => $r['requester_id'] === $dup)) === 0, 'the merged row is off the list');
[$c, $b] = act($lena, '/requesters/merge.php', ['requester' => $dup, 'into' => $bob]);
ok($c === 422 && msg($b) === 'One of them was merged already.', 'merging it again: 422');
$ext2 = external('carl@initech.invalid', 'SMOKE Carl');
[$c, $b] = act($lena, '/requesters/merge.php', ['requester' => $ext2, 'into' => $mreq]);
ok($c === 200 && (int) one('SELECT merged_into_id FROM requesters WHERE id = :r', ['r' => $ext2]) === $mreq && (int) one('SELECT requester_id FROM requester_emails WHERE email = :e', ['e' => 'carl@initech.invalid']) === $mreq, 'an external into a member: allowed, the address now reaches Marco');
finish();
